#ifndef ZOVUTILS_TRUNCATE_BACKEND_H
#define ZOVUTILS_TRUNCATE_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdint.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
static inline int zov_trunc_size(const char*s,off_t*out,int*relative){char*e;errno=0;long long n=strtoll(s,&e,10);if(errno||e==s)return 0;int sign=1;if(n<0){if(n==LLONG_MIN)return 0;sign=-1;n=-n;}if(*e=='%'&&sign>0){return 0;}unsigned long long mul=1;if(*e){if(e[1])return 0;char c=*e;if(c=='k'||c=='K')mul=1024ULL;else if(c=='m'||c=='M')mul=1024ULL*1024;else if(c=='g'||c=='G')mul=1024ULL*1024*1024;else if(c=='t'||c=='T')mul=1024ULL*1024*1024*1024;else if(c=='p'||c=='P')mul=1024ULL*1024*1024*1024*1024;else if(c=='b')mul=512;else return 0;}if((unsigned long long)n>(unsigned long long)INT64_MAX/mul)return 0;*out=(off_t)(n*(long long)mul);*relative=sign<0?-1:(s[0]=='+'?1:0);return 1;}
static inline int zov_truncate_run(int argc,char**argv){off_t size=0;int have=0,nocreate=0,end=0,relative=0;const char*ref=NULL;char**files=(char**)malloc((size_t)(argc+1)*sizeof(char*));if(!files)return 1;int nf=0;for(int i=0;i<argc;i++){const char*a=argv[i];if(!end&&!strcmp(a,"--")){end=1;continue;}if(!end&&(!strcmp(a,"--help")||!strcmp(a,"--version"))){if(!strcmp(a,"--version")){puts("truncate (zovutils) 0.10.26");free(files);return 0;}puts("Usage: truncate OPTION... FILE...\nShrink or extend the size of each FILE to the specified size.\n  -c, --no-create        do not create files that do not exist\n  -r, --reference=RFILE  use the size of RFILE\n  -s, --size=SIZE        set or adjust the file size by SIZE bytes\n      --help             display this help and exit\n      --version          output version information and exit");free(files);return 0;}if(!end&&(!strcmp(a,"-c")||!strcmp(a,"--no-create"))){nocreate=1;continue;}if(!end&&(!strcmp(a,"-s")||!strcmp(a,"--size"))){if(i+1>=argc){fprintf(stderr,"truncate: option requires an argument -- 's'\n");free(files);return 1;}if(!zov_trunc_size(argv[++i],&size,&relative)){fprintf(stderr,"truncate: Invalid number: '%s'\n",argv[i]);free(files);return 1;}have=1;continue;}if(!end&&!strncmp(a,"--size=",7)){if(!zov_trunc_size(a+7,&size,&relative)){fprintf(stderr,"truncate: Invalid number: '%s'\n",a+7);free(files);return 1;}have=1;continue;}if(!end&&(!strcmp(a,"-r")||!strcmp(a,"--reference"))){if(i+1>=argc){fprintf(stderr,"truncate: option requires an argument -- 'r'\n");free(files);return 1;}ref=argv[++i];continue;}if(!end&&!strncmp(a,"--reference=",12)){ref=a+12;continue;}if(!end&&a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"truncate: unrecognized option '%s'\nTry 'truncate --help' for more information.\n",a);free(files);return 1;}files[nf++]=(char*)a;}if(!have&&!ref){fprintf(stderr,"truncate: missing file operand\nTry 'truncate --help' for more information.\n");free(files);return 1;}if(!nf){fprintf(stderr,"truncate: missing file operand\nTry 'truncate --help' for more information.\n");free(files);return 1;}if(ref){struct stat st;if(stat(ref,&st)){fprintf(stderr,"truncate: cannot stat '%s': %s\n",ref,strerror(errno));free(files);return 1;}size=st.st_size;relative=0;have=1;}int status=0;for(int i=0;i<nf;i++){struct stat st;int exists=stat(files[i],&st)==0;if(!exists)memset(&st,0,sizeof(st));if(!exists&&nocreate)continue;int fd=open(files[i],O_WRONLY|(exists?0:O_CREAT),0666);if(fd<0){fprintf(stderr,"truncate: cannot open '%s' for writing: %s\n",files[i],strerror(errno));status=1;continue;}off_t target=size;if(relative>0)target=st.st_size+size;else if(relative<0)target=st.st_size-size;if(target<0)target=0;if(ftruncate(fd,target)<0){fprintf(stderr,"truncate: failed to truncate '%s' at %lld bytes: %s\n",files[i],(long long)target,strerror(errno));status=1;}close(fd);}free(files);return status;}
#endif
